mapper.select:
SELECT * FROM push_notifications
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit}

mapper.update:
UPDATE push_notifications
SET status = #{status},
    error_message = #{errorMessage}
WHERE id = #{id}

UPDATE push_notifications
SET status = 'sent',
    sent_at = #{sentAt}
WHERE id = #{id}

UPDATE push_notifications
SET status = 'read',
    read_at = #{readAt}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*)
FROM push_notifications
WHERE user_id = #{userId}
  AND status IN ('sent', 'read')
  AND sent_at >= #{startOfDay}

mapper.update:
UPDATE push_notifications
SET status = 'cancelled'
WHERE user_id = #{userId}
  AND notification_type = #{notificationType}
  AND status = 'pending'

mapper.select:
SELECT COUNT(*)
FROM push_notifications
WHERE user_id = #{userId}
  AND status IN ('sent', 'read')
  AND sent_at >= #{since}

SELECT JSON_UNQUOTE(JSON_EXTRACT(data, '$.messageType'))
FROM push_notifications
WHERE user_id = #{userId}
  AND status IN ('sent', 'read')
  AND sent_at >= #{since}
  AND data IS NOT NULL
ORDER BY sent_at DESC
LIMIT #{limit}
